assert all(IND[k]["sig"] for k in ["SC_FOMO_IDQ", "AR_FOMO_IDQ", "AL_AIU_IDQ", "SME_AIU_IDQ", "SME_FOMO_IDQ"])
assert inv["metric"]["cfi"] - inv["configural"]["cfi"] > -.01 and (inv["metric"]["cfi"] - inv["scalar"]["cfi"] <= .01 or R["invariance_freed"])
assert gp("FOMO~AR")["diff"] > 0 and gp("FOMO~AR")["boot_lo"] > 0 and gp("IDQ~FOMO")["diff"] < 0 and gp("IDQ~FOMO")["boot_hi"] < 0
assert R["ml_tests"]["RF"]["p"] < .05 and R["ml_tests"]["GBM"]["p"] < .05 and R["ml_tests"]["RF"]["diff_r2"] > 0
