# ---- شکل‌ها
def fig_model(path, results):
    g = Diagram(11.5, 6.2)
    for k, y in [("SC", 50), ("AR", 36), ("SME", 21), ("AL", 6)]: g.node(k, 13, y, NM[k] if k != "SME" else "مواجهه با محتوای\nشبکه‌ها", w=22, h=9)
    g.node("FOMO", 52, 41, "فومو", w=17, h=10); g.node("AIU", 52, 12, "استفاده از اطلاعات\nحسابداری", w=24, h=11); g.node("IDQ", 88, 27, "کیفیت تصمیم\nسرمایه‌گذاری", w=20, h=12)
    def L(k, h): return (fl.fa(h) if not results else fl.num(P[k]["beta"]) + " " + sig(P[k]["p"]))
    g.edge("SC", "FOMO", L("FOMO~SC", "H1 (+)"), off=(0, 2.5)); g.edge("AR", "FOMO", L("FOMO~AR", "H2 (+)"), off=(-2, 2.5))
    g.edge("SME", "FOMO", L("FOMO~SME", "(+)") if results else None, off=(-4, 0), dashed=not results)
    g.edge("SME", "AIU", L("AIU~SME", "H3 (−)"), off=(0, -2.5)); g.edge("AL", "AIU", L("AIU~AL", "H4 (+)"), off=(0, -2.5))
    g.edge("FOMO", "IDQ", L("IDQ~FOMO", "H5 (−)"), off=(3, 2.5)); g.edge("AIU", "IDQ", L("IDQ~AIU", "H6 (+)"), off=(3, -2.5))
    g.ax.text(50, 53, fl.fa("مقایسهٔ گروهی: تجربهٔ زیان در ریزش بورس (بله / خیر)") , fontsize=9, ha="center", color="#555")
    g.save(path)
fig_model(os.path.join(OUT, "fig1_conceptual.png"), False); fig_model(os.path.join(OUT, "fig2_results.png"), True)
def fig_forest(path):
    lab = {"FOMO~SC": "مقایسهٔ اجتماعی ← فومو", "FOMO~AR": "پشیمانی پیش‌بینی‌شده ← فومو", "FOMO~SME": "مواجهه ← فومو", "AIU~AL": "سواد حسابداری ← اطلاعات حسابداری",
           "AIU~SME": "مواجهه ← اطلاعات حسابداری", "IDQ~FOMO": "فومو ← کیفیت تصمیم", "IDQ~AIU": "اطلاعات حسابداری ← کیفیت تصمیم"}
    fig, ax = plt.subplots(figsize=(7.4, 4.4)); ks = list(lab)[::-1]
    for i, k in enumerate(ks):
        v = GP[k]; c = "#b2182b" if v["boot_lo"] * v["boot_hi"] > 0 else "#555555"
        ax.plot([v["boot_lo"], v["boot_hi"]], [i, i], color=c, lw=2.2); ax.plot(v["diff"], i, "o", color=c)
    ax.axvline(0, color="#222", lw=1, ls="--"); ax.set_yticks(range(len(ks))); ax.set_yticklabels([fl.fa(lab[k]) for k in ks], fontsize=9)
    xt = ax.get_xticks(); ax.set_xticks(xt); ax.set_xticklabels([fl.num(t, 1) for t in xt])
    ax.set_xlabel(fl.fa("تفاوت ضریب (دارای تجربهٔ زیان − فاقد تجربهٔ زیان) و فاصلهٔ اطمینان خودگردان ۹۵٪")); ax.spines[["top", "right"]].set_visible(False)
    fig.tight_layout(); fig.savefig(path, dpi=220, facecolor="white"); plt.close(fig)
fig_forest(os.path.join(OUT, "fig3_group_differences.png"))
def fig_shap(path):
    sv = np.load(os.path.join(OUT, "shap_values.npy")); ft = pd.read_csv(os.path.join(OUT, "features.csv"))
    imp = pd.Series(np.abs(sv).mean(0), index=ft.columns).sort_values(); order = list(imp.index)
    fig, axs = plt.subplots(1, 2, figsize=(10.5, 4.6))
    axs[0].barh(range(len(order)), imp.values, color="#2166ac"); axs[0].set_yticks(range(len(order))); axs[0].set_yticklabels(order, fontsize=9)
    axs[0].set_xlabel(fl.fa("میانگین قدر مطلق SHAP")); xt = axs[0].get_xticks(); axs[0].set_xticks(xt); axs[0].set_xticklabels([fl.num(t, 2) for t in xt])
    rng = np.random.default_rng(1)
    for i, f in enumerate(order):
        j = list(ft.columns).index(f); v = ft[f].values; vz = (v - v.min()) / (v.max() - v.min() + 1e-9)
        axs[1].scatter(sv[:, j], i + rng.uniform(-.28, .28, len(v)), c=vz, cmap="coolwarm", s=8, alpha=.75)
    axs[1].set_yticks(range(len(order))); axs[1].set_yticklabels(order, fontsize=9); axs[1].axvline(0, color="#222", lw=.8)
    axs[1].set_xlabel(fl.fa("مقدار SHAP (اثر بر پیش‌بینی کیفیت تصمیم)")); xt = axs[1].get_xticks(); axs[1].set_xticks(xt); axs[1].set_xticklabels([fl.num(t, 1) for t in xt])
    for a in axs: a.spines[["top", "right"]].set_visible(False)
    fig.tight_layout(); fig.savefig(path, dpi=220, facecolor="white"); plt.close(fig)
fig_shap(os.path.join(OUT, "fig4_shap.png"))

