d.heading("۴-۲. مدل ساختاری و اثرهای غیرمستقیم", 2)
d.para(f"مقایسهٔ اجتماعی ({stat('FOMO~SC')}) و پشیمانی پیش‌بینی‌شده ({stat('FOMO~AR')}) فومو را افزایش دادند (فرضیه‌های ۱ و ۲). مواجهه با محتوای شبکه‌ها استفاده از اطلاعات حسابداری را کاهش داد ({stat('AIU~SME')}؛ فرضیهٔ ۳) و سواد حسابداری آن را افزایش داد ({stat('AIU~AL')}؛ فرضیهٔ ۴). فومو کیفیت تصمیم را کاهش داد ({stat('IDQ~FOMO')}؛ فرضیهٔ ۵) و استفاده از اطلاعات حسابداری آن را افزایش داد ({stat('IDQ~AIU')}؛ فرضیهٔ ۶). اثر مستقیم سواد حسابداری بر کیفیت تصمیم معنادار نبود ({S('β = ' + format(P['IDQ~AL']['beta'], '.2f'))}؛ {pt(P['IDQ~AL']['p'])})، یعنی اثر آن عمدتاً از راه استفادهٔ عملی از اطلاعات حسابداری منتقل می‌شود. تجربهٔ زیان فومو را بالاتر برد ({S('β = ' + format(P['FOMO~LE']['beta'], '.2f'))}). بر پایهٔ نمرات ترکیبی، R² فومو {f2(R['r2_comp']['FOMO'])}، استفاده از اطلاعات حسابداری {f2(R['r2_comp']['AIU'])} و کیفیت تصمیم {f2(R['r2_comp']['IDQ'])} بود.")
def prow(l, k, h): v = P[k]; return [l, h, num(v["b"], 3), num(v["beta"], 3), f3(v["se"]), num(v["z"], 2), pt(v["p"]), sig(v["p"])]
d.table("جدول ۴. ضرایب مسیر ساختاری", ["مسیر", "فرضیه", "b", "β", "خطای معیار", "z", "p", "معناداری"],
        [prow("مقایسهٔ اجتماعی ← فومو", "FOMO~SC", "۱"), prow("پشیمانی پیش‌بینی‌شده ← فومو", "FOMO~AR", "۲"), prow("مواجهه ← استفاده از اطلاعات حسابداری", "AIU~SME", "۳"),
         prow("سواد حسابداری ← استفاده از اطلاعات حسابداری", "AIU~AL", "۴"), prow("فومو ← کیفیت تصمیم", "IDQ~FOMO", "۵"), prow("استفاده از اطلاعات حسابداری ← کیفیت تصمیم", "IDQ~AIU", "۶"),
         prow("مواجهه ← فومو (کنترلی)", "FOMO~SME", "—"), prow("سواد حسابداری ← کیفیت تصمیم (مستقیم)", "IDQ~AL", "—"), prow("تجربهٔ زیان ← فومو (کنترلی)", "FOMO~LE", "—")],
        widths=[3300, 700, 800, 800, 850, 800, 900, 850], size=22, note="توضیح: معناداری: ∗∗∗ ‏p<۰٫۰۰۱، ∗∗ ‏p<۰٫۰۱، ∗ ‏p<۰٫۰۵؛ متغیرهای کنترل: تجربهٔ زیان و سابقه.")
